import * as THREE from 'three/webgpu';
import { texture, uv, vec2, mix, uniform, time, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'features-card-1-plane';

  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);

  const imageUrl = config?.assets?.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  const map = ctx.textureLoader.load(imageUrl);
  map.colorSpace = THREE.SRGBColorSpace;
  map.needsUpdate = true;

  const material = new THREE.MeshBasicNodeMaterial();

  const texNode = texture(map, uv());

  // subtle engineered gradient overlay (ink -> surface) for machined-metal-adjacent flat look
  const inkColor = uniform(new THREE.Color(config?.visual?.colors?.ink || '#16161d'));
  const surfaceColor = uniform(new THREE.Color(config?.visual?.colors?.surface || '#0b0b10'));

  const gradientFactor = uv().y;
  const gradient = mix(surfaceColor, inkColor, gradientFactor);

  // subtle grain via time-varying noise-like blend (cheap, static-feeling since amplitude tiny)
  const grainAmount = float(0.02);
  const grainNode = mix(texNode.rgb, gradient, grainAmount);

  material.colorNode = vec2 ? texNode : texNode; // keep base texture primary
  material.colorNode = texNode;
  material.transparent = true;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'features-card-1-mesh';
  group.add(mesh);

  const pos = config?.scenePlacement?.position || [-3.2, -0.3, 0];
  const rot = config?.scenePlacement?.rotation || [0, 0, 0];
  const scl = config?.scenePlacement?.scale || [1, 1, 1];

  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
  };

  return group;
}
